import unittest
from pricing.money import Money, ZERO
from pricing.cart import cart_total
from pricing.format import format_money
from pricing.report import to_csv
from pricing.tax import apply_tax


class CartTests(unittest.TestCase):
    def test_three_dimes(self):
        self.assertEqual(cart_total([("widget", Money(0.10), 3)]), Money(0.30))

    def test_csv_has_two_decimals(self):
        self.assertEqual(to_csv([("widget", Money(0.10), 3)]), "name,qty,total\nwidget,3,0.30\n")

    def test_totals_do_not_drift_over_many_lines(self):
        lines = [(f"dime{i}", Money(0.10), 1) for i in range(1000)]
        self.assertEqual(cart_total(lines), Money(100.00))

    def test_empty_cart_is_zero(self):
        self.assertEqual(cart_total([]), ZERO)


class MoneyTests(unittest.TestCase):
    def test_stored_as_integer_cents(self):
        self.assertIsInstance(Money(0.10).cents, int)
        self.assertEqual(Money(0.10).cents, 10)
        self.assertEqual(Money.from_cents(10), Money(0.10))

    def test_equal_values_hash_alike(self):
        self.assertEqual(len({Money(0.10), Money(0.10)}), 1)

    def test_negation_round_trips(self):
        self.assertEqual(Money(0.10) + -Money(0.10), ZERO)

    def test_is_immutable(self):
        with self.assertRaises(AttributeError):
            Money(0.10).cents = 99


class DisplayTests(unittest.TestCase):
    def test_format_is_unchanged(self):
        self.assertEqual(format_money(Money(1234567.89)), "$1,234,567.89")
        self.assertEqual(format_money(-Money(1234567.89)), "-$1,234,567.89")
        self.assertEqual(format_money(ZERO), "$0.00")

    def test_tax_rounding_is_unchanged(self):
        self.assertEqual(apply_tax(Money(19.99), 0.0825), Money(21.64))
        self.assertEqual(apply_tax(Money(0.10), 0.05), Money(0.11))
        self.assertEqual(apply_tax(Money(100), 0.0), Money(100))

